def build_people():
    people = []
    for i, row in enumerate(PEOPLE.strip().splitlines(), 1):
        name, era, field, title, profile, tags, summary, strength, caution, fact, refs = row.split("|")
        people.append({
            "id": f"H{i:03}", "name": name, "era": era, "field": field,
            "typeTitle": title, "profile": [int(x) for x in profile.split(",")],
            "tags": tags.split("、"),
            "summary": f"在本产品的设定中，{name}代表这样的倾向：{summary.removeprefix('你')}",
            "strength": strength,
            "caution": caution, "historicalContext": fact,
            "shareText": f"我的历史同频人物是{name}，本次关键词是{'、'.join(tags.split('、'))}。",
            "profileRationale": f"本产品从以下材料主题提炼匹配形象：{fact} 六维数值为编辑设定，不是对真实人格的测量。",
            "sourceCandidates": refs.split("；"),
            "reviewStatus": "待史料逐条核验与内容评审",
        })
    return people


