def build_questions():
    questions = []
    orders = [(0, 1, 2, 3), (2, 0, 3, 1), (1, 3, 0, 2), (3, 2, 1, 0)]
    for i, (dimension, title, choices) in enumerate(QUESTION_SEEDS, 1):
        axis_index = next(j for j, d in enumerate(DIMENSIONS) if d["id"] == dimension)
        round_index = (i - 1) // 6
        by_score = {s: t for t, s in choices}
        choices = [(by_score[s], s) for s in orders[(axis_index + round_index) % 4]]
        questions.append({"id": f"Q{i:02}", "dimension": dimension, "title": title,
                          "options": [{"id": chr(65+j), "text": t, "score": s}
                                      for j, (t, s) in enumerate(choices)]})
    return questions


def write_json(path, value):
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def main():
    people = build_people()
    questions = build_questions()
    write_json(ROOT / "data/people.json", {"version": VERSION, "dimensions": DIMENSIONS, "people": people})
    write_json(ROOT / "data/questions.json", {"version": VERSION, "questions": questions})
